DROP VIEW public.community_feed_posts, public.community_feed_replies;
CREATE OR REPLACE FUNCTION public.community_feed_posts() RETURNS TABLE(id uuid,author_id uuid,mine boolean,author_name text,is_anonymous boolean,topic text,title text,body text,created_at timestamptz,image_path text,poll_options jsonb,source_url text,is_verified boolean,is_bot boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,CASE WHEN p.is_anonymous THEN NULL ELSE p.user_id END,p.user_id=auth.uid(),CASE WHEN p.is_anonymous THEN 'Anónimo' ELSE p.author_name END,p.is_anonymous,p.topic,p.title,p.body,p.created_at,p.image_path,p.poll_options,p.source_url,p.is_verified,p.is_bot FROM public.community_posts p WHERE auth.uid() IS NOT NULL ORDER BY p.created_at DESC LIMIT 200 $$;
CREATE OR REPLACE FUNCTION public.community_feed_replies() RETURNS TABLE(id uuid,post_id uuid,parent_reply_id uuid,author_id uuid,mine boolean,author_name text,is_anonymous boolean,body text,created_at timestamptz,image_path text,audio_path text,is_bot boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.post_id,r.parent_reply_id,CASE WHEN r.is_anonymous THEN NULL ELSE r.user_id END,r.user_id=auth.uid(),CASE WHEN r.is_anonymous THEN 'Anónimo' ELSE r.author_name END,r.is_anonymous,r.body,r.created_at,r.image_path,r.audio_path,r.is_bot FROM public.community_replies r WHERE auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.community_posts p WHERE p.id=r.post_id) ORDER BY r.created_at ASC LIMIT 2000 $$;
REVOKE ALL ON FUNCTION public.community_feed_posts(),public.community_feed_replies(),public.community_guard(),public.community_reaction_guard() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.community_guard(),public.community_reaction_guard() FROM authenticated;
GRANT EXECUTE ON FUNCTION public.community_feed_posts(),public.community_feed_replies() TO authenticated;
REVOKE SELECT ON public.community_posts,public.community_replies FROM authenticated;
GRANT SELECT (id) ON public.community_posts TO authenticated;
GRANT SELECT (id) ON public.community_replies TO authenticated;